use pulldown_cmark::Options;
fn render(input: &str, opts: Options) -> String {
    let parser = pulldown_cmark::Parser::new_ext(input, opts);
    let mut html = String::new();
    pulldown_cmark::html::push_html(&mut html, parser);
    html.trim().to_string()
}
fn main() {
    let mut strike = Options::empty();
    strike.insert(Options::ENABLE_STRIKETHROUGH);
    let mut both = Options::empty();
    both.insert(Options::ENABLE_STRIKETHROUGH);
    both.insert(Options::ENABLE_SUBSCRIPT);
    let mut sup = Options::empty();
    sup.insert(Options::ENABLE_SUPERSCRIPT);
    let mut hl = Options::empty();
    hl.insert(Options::ENABLE_HIGHLIGHT);

    println!("strike ~~a [x](https://x)~~ b: {}", render("~~a [x](https://x)~~ b", strike));
    println!("both ~~a ~b~~ c~: {}", render("~~a ~b~~ c~", both));
    println!("sup ^a [x](https://x)^: {}", render("^a [x](https://x)^", sup));
    println!("sup(off) ^a [x](https://x)^: {}", render("^a [x](https://x)^", Options::empty()));
    println!("hl(off) ==a [x](https://x)==: {}", render("==a [x](https://x)==", Options::empty()));
    println!("hl(on) ==a [x](https://x)==: {}", render("==a [x](https://x)==", hl));
    println!("only-strike single ~a [x](https://x)~: {}", render("~a [x](https://x)~", strike));
}
EOF
